Voici un exemple de programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string fileName, wordToCount;
    int count = 0;

    // Prompt user for file name and word to count
    std::cout << "Enter file name: ";
    std::cin >> fileName;

    std::cout << "Enter word to count: ";
    std::cin >> wordToCount;

    // Open the file for reading
    std::ifstream file(fileName);
    if (!file) {
        std::cerr << "Error: could not open file " << fileName << std::endl;
        return 1;
    }

    // Read the file line by line and count occurrences of the word
    std::string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
            count++;
            pos += wordToCount.length();
        }
    }

    // Close the file
    file.close();

    // Display the count
    std::cout << "The word \"" << wordToCount << "\" appears " << count << " times in " << fileName << std::endl;

    return 0;
}
```

